    mod = 10**9 + 7
    total_sequences = pow(n-1, n-1, mod)
    invalid_sequences = 0

    def dfs(path, current_sum):
        nonlocal invalid_sequences
        if len(path) == n-1:
            if current_sum % n == 0:
                invalid_sequences += 1
            return
        for i in range(1, n):
            dfs(path + [i], current_sum + i)

    dfs([], 0)

    valid_sequences = total_sequences - invalid_sequences
    if k > valid_sequences:
