    result = []
    remaining_k = k
    for i in range(n-1, 0, -1):
        total_combinations = binomial_coefficient(n-1, i-1, mod)
        valid_combinations = total_combinations - binomial_coefficient(invalid_sequences, i-1, mod)
        if remaining_k <= valid_combinations:
            result.append(i)
            remaining_k -= valid_combinations
        else:
            remaining_k -= valid_combinations

    return result[::-1]

