from math import factorial

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def mod_inverse(a, m):
    m0, x0, x1 = m, 0, 1
    if m == 1:
        return 0
    while a > 1:
        q = a // m
        m, a = a % m, m
        x0, x1 = x1 - q * x0, x0
    if x1 < 0:
        x1 += m0
    return x1

def binomial_coefficient(n, k, mod):
    if k > n:
        return 0
    num = factorial(n) % mod
    den = (factorial(k) * factorial(n - k)) % mod
    return num * mod_inverse(den, mod) % mod

def nth_valid_sequence(n, k):
    mod = 10**9 + 7
    dp = [[0] * n for _ in range(n)]
    dp[0][0] = 1

    for i in range(1, n):
        for j in range(n):
            dp[i][j] = dp[i-1][j]
            if j >= 1:
                dp[i][j] += dp[i-1][j-1]

    def count_invalid_sequences(length):
        if length == 1:
            return 0
        invalid_count = 0
        for i in range(1, length):
            invalid_count += dp[length-1][i-1]
        return invalid_count

    def get_kth_sequence(length, k):
        if length == 1:
            return [1]

        invalid_count = count_invalid_sequences(length)
        if k <= invalid_count:
            return [1] + get_kth_sequence(length-1, k)

        k -= invalid_count
        for i in range(1, n):
            if k <= dp[length-1][i-1]:
                return [i] + get_kth_sequence(length-1, k)
            k -= dp[length-1][i-1]

    return get_kth_sequence(n-1, k)

